-- =========================================================================
-- Idempotent Species Image and Credit Synchronization Script
-- Target: public.species table in Supabase PostgreSQL
-- Purpose: Eliminates all legacy/external stock photo URLs from reference_images,
--          sets reference_images to local path ARRAY['/species/{id}.webp']::text[],
--          and attaches verified image_credit metadata from credits.json for all 150 species.
-- =========================================================================

begin;

update public.species set reference_images = ARRAY['/species/0.webp']::text[], image_credit = '{"observer":"pikun","license":"CC-BY-NC","source_url":"https://www.inaturalist.org/photos/685727293"}'::jsonb where id = 0;
